    t = std::move(made);
    q = List<I32>{};
    ro = kern::to<Int>(kern::formula([](Float open_m, Float step) -> Float { return kern::math::max(1.0, kern::math::wrap32s(kern::math::round(kern::math::div(kern::math::div(open_m, step), 2.0)))); }, open_m, step));
